import json
import os
import re
import subprocess
import whisper

INPUT_PATH = "/root/input.mp4"
ANNOTATIONS_PATH = "/root/annotations.json"
OUTPUT_PATH = "/root/output.mp4"

SINGLE_FILLERS = {
    "um", "uh", "hum", "hmm", "mhm",
    "like", "yeah", "so", "well", "okay", "basically",
}
PHRASE_FILLERS = {
    "you know", "i mean", "kind of", "i guess",
}

PAD_BEFORE = 0.02
PAD_AFTER = 0.02
MERGE_GAP = 0.02


def normalize(word: str) -> str:
    return re.sub(r"[^a-z]", "", word.lower())


def transcribe_words(path: str):
    model = whisper.load_model("tiny")
    result = model.transcribe(path, word_timestamps=True, language="en")

    words = []
    for segment in result.get("segments", []):
        for w in segment.get("words", []):
            raw = w.get("word", "")
            clean = normalize(raw)
            if not clean:
                continue
            words.append({
                "raw": raw,
                "clean": clean,
                "start": float(w["start"]),
                "end": float(w["end"]),
            })

    return words


def detect_fillers(words):
    matches = []

    for item in words:
        if item["clean"] in SINGLE_FILLERS:
            matches.append({
                "word": item["clean"],
                "timestamp": item["start"],
                "start": item["start"],
                "end": item["end"],
            })

    # All target phrases are two words
    for i in range(len(words) - 1):
        pair = f"{words[i]['clean']} {words[i + 1]['clean']}"
        if pair in PHRASE_FILLERS:
            matches.append({
                "word": pair,
                "timestamp": words[i]["start"],
                "start": words[i]["start"],
                "end": words[i + 1]["end"],
            })

    matches.sort(key=lambda x: x["timestamp"])
    return matches


def write_annotations(matches, path: str):
    annotations = [
        {"word": m["word"], "timestamp": round(m["timestamp"], 3)}
        for m in matches
    ]
    with open(path, "w") as f:
        json.dump(annotations, f, indent=2)


def build_segments(matches):
    segments = []
    for m in matches:
        start = max(0.0, m["start"] - PAD_BEFORE)
        end = m["end"] + PAD_AFTER
        if end > start:
            segments.append((start, end))

    if not segments:
        return []

    segments.sort()
    merged = [list(segments[0])]
    for start, end in segments[1:]:
        prev_start, prev_end = merged[-1]
        if start <= prev_end + MERGE_GAP:
            merged[-1][1] = max(prev_end, end)
        else:
            merged.append([start, end])
    return [(s, e) for s, e in merged]


def extract_and_concat(segments, input_path: str, output_path: str):
    if not segments:
        raise RuntimeError("No filler word segments detected; output video not created.")

    temp_dir = "/tmp/filler_segments"
    os.makedirs(temp_dir, exist_ok=True)

    segment_files = []
    for idx, (start, end) in enumerate(segments):
        out_path = os.path.join(temp_dir, f"seg_{idx:04d}.mp4")
        cmd = [
            "ffmpeg", "-y", "-loglevel", "error",
            "-i", input_path,
            "-ss", f"{start:.3f}",
            "-to", f"{end:.3f}",
            "-c:v", "libx264", "-preset", "veryfast", "-crf", "23",
            "-c:a", "aac",
            "-movflags", "+faststart",
            "-reset_timestamps", "1",
            out_path,
        ]
        subprocess.run(cmd, check=True)
        segment_files.append(out_path)

    list_path = os.path.join(temp_dir, "concat_list.txt")
    with open(list_path, "w") as f:
        for seg in segment_files:
            f.write(f"file '{seg}'\n")

    concat_cmd = [
        "ffmpeg", "-y", "-loglevel", "error",
        "-f", "concat", "-safe", "0", "-i", list_path,
        "-c", "copy", output_path,
    ]
    subprocess.run(concat_cmd, check=True)


def main():
    words = transcribe_words(INPUT_PATH)
    matches = detect_fillers(words)
    write_annotations(matches, ANNOTATIONS_PATH)

    segments = build_segments(matches)
    extract_and_concat(segments, INPUT_PATH, OUTPUT_PATH)


if __name__ == "__main__":
    main()
